sys_properties.value:
[
  {
    "category": "Plugin Management",
    "actions": [
      {
        "type": "Activate Plugins",
        "description": "Enable required functionalities by activating  the necessary plugins .",
        "short_description": "Activate the New Plugins",
        "instruction": "The following plugins are not activated. Please activate them:",
        "plugins": ["plugin1", "plugin2"]
      },
      {
        "type": "Upgrade Plugins",
        "description": "Enhance system performance and security by upgrading plugins to the latest versions.",
        "short_description": "Upgrade Plugins",
        "instruction": "The following plugins have available upgrades. Please upgrade them:",
        "plugins": ["plugin1", "plugin2"]
      }
    ]
  },
  {
    "category": "Property Management",
    "actions": [
      {
        "type": "Update Property",
        "description": "Ensure system properties are set to the correct suggested values.",
        "short_description": "Update System Properties",
        "instruction": "The suggested values for the following properties need updating:",
        "properties": ["property1", "property2"]
      }
    ]
  },
  {
    "category": "User Role Management",
    "actions": [
      {
        "type": "Assign Roles and Permissions",
        "description": "Assign users to the appropriate roles and groups to ensure proper access.",
        "short_description": "Manage User Roles",
        "instruction": "The following users need role assignments. If admin access is required, assign them to the 'SAM Implementation Admin' group."
      }
    ]
  },
  {
    "category": "Normalization Data Service",
    "actions": [
      {
        "type": "Enable Normalization",
        "description": "Ensure data consistency by enabling normalization for core company records.",
        "short_description": "Activate Normalization",
        "instruction": "Normalization for core company data is not yet enabled. Please complete the guided setup."
      }
    ]
  },
  {
    "category": "Top Publisher Selection",
    "actions": [
      {
        "type": "Select Publisher",
        "description": "Choose a top publisher for effective license position (ELP) management.",
        "short_description": "Select Top Publisher",
        "instruction": "Select the publisher for which you want to generate the Effective License Position (ELP)."
      }
    ]
  },
  {
    "category": "Manual Data Import",
    "actions": [
      {
        "type": "Import Contract Data",
        "description": "Load contract data into the system.",
        "short_description": "Import Contracts",
        "instruction": "Contract data needs to be imported. Please proceed with the upload."
      },
      {
        "type": "Import Entitlement Data",
        "description": "Load entitlement data for software asset management.",
        "short_description": "Import Entitlements",
        "instruction": "Entitlement data needs to be imported. Please proceed with the upload."
      }
    ]
  },
  {
    "category": "Normalization",
    "actions": [
      {
        "type": "Enable Opt-in",
        "description": "Enable normalization opt-in to standardize software data.",
        "short_description": "Enable Normalization Opt-in",
        "instruction": "Please enable the normalization opt-in to proceed."
      },
      {
        "type": "Define Normalization Rules",
        "description": "Set up normalization rules to streamline software categorization.",
        "short_description": "Configure Normalization Rules",
        "instruction": "Define the normalization rules for standardizing software records."
      }
    ]
  },
  {
    "category": "Validate Software Model",
    "actions": [
      {
        "type": "Check Parent-Child Relationships",
        "description": "Ensure parent-child relationships are correctly configured for software models.",
        "short_description": "Validate Parent-Child Links",
        "instruction": "Verify that all parent-child relationships are correctly set up."
      },
      {
        "type": "Review License Management",
        "description": "Analyze the License Management report for any compliance violations.",
        "short_description": "Review License Compliance",
        "instruction": "Check the License Management report for any issues."
      },
      {
        "type": "Verify DMAP (Discovery Map)",
        "description": "Open the software model record and review the DMAP field.",
        "short_description": "Check DMAP Field",
        "instruction": "Review the Discovery Map (DMAP) for accuracy."
      },
      {
        "type": "Assess Inference Percentage",
        "description": "Check the inference percentage for the software model to ensure accurate classification.",
        "short_description": "Validate Inference Percentage",
        "instruction": "Assess the inference percentage for this software model."
      },
      {
        "type": "Confirm Downgrade Rights",
        "description": "Verify downgrade rights for software products to ensure compliance.",
        "short_description": "Check Downgrade Rights",
        "instruction": "Confirm that downgrade rights are properly assigned to software products."
      }
    ]
  },
  {
    "category": "Custom Scripts",
    "actions": [
      {
        "type": "Install Custom Scripts",
        "description": "Deploy tailored scripts essential for software management.",
        "short_description": "Deploy Custom Scripts",
        "instruction": "Install the required custom scripts to manage software effectively."
      }
    ]
  },
  {
    "category": "Effective License Position",
    "actions": [
      {
        "type": "Validate ELP",
        "description": "Ensure effective license position (ELP) is accurately reported.",
        "short_description": "Verify Effective License Position",
        "instruction": "Review and validate the ELP report."
      }
    ]
  },
  {
    "category": "Documentation",
    "actions": [
      {
        "type": "Review Documentation",
        "description": "Study the provided documentation to understand software setup and management.",
        "short_description": "Review Software Documentation",
        "instruction": "Go through the relevant documents for software setup and usage guidelines."
      }
    ]
  }
]
